entries[362051] = { ["name"] = "Ephemere Ladung", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Rückgewinner erfüllt zwei Spielercharaktere mit ephemerer Energie. Bei Ablauf versuchen die Ladungen, sich durch einen Strahl zu verbinden und dadurch beiden Spielercharakteren 60 kosmischen Schaden zuzufügen.\n\nWenn der Strahl durch Halondrus unterbrochen wird, laufen die Ladungen ab und verursachen keinen Schaden." }
entries[362052] = { ["name"] = "Zurückgewinnen", ["text"] = "Sofort\nHalondrus aktiviert einen Schild, der Schaden in Höhe von 4% seiner maximalen Gesundheit absorbiert.\n\nSolange der Schild hält, verursacht Halondrus alle 1 Sek. 12531 kosmischen Schaden und zieht Spielercharaktere sowie Ephemera zu seiner Position. Dieser Effekt wird mit der Zeit stärker." }
