entries[362055] = { ["name"] = "Verlorene Seele", ["text"] = "300 Meter Reichweite\nSofort\nSolange die Seelen von Spielercharakteren verbannt sind, können sie Anduins Seele helfen.\n\nWenn Anduins Zweifel besiegt und seine Hoffnung wiederhergestellt wird, erhält er Willenskraft.\n\nBei Entfernung dieses Effekts werden Spielercharaktere mit ' Gezeichnete Seele ' belegt." }
