entries[363297] = { ["name"] = "Kolossale Seelenfetzerschlundratte", ["text"] = "Wirken in 1.5 sek.\nBeschwört Eure kolossale Seelenfetzerschlundratte oder gibt sie wieder frei.\n\"Das unglaubliche Können, das Ihr im Turm des Kerkermeisters demonstriert habt, hat dieser furchtgebietenden Kreatur genug Respekt eingeflößt, um es als Reittier nutzen zu können.\"\nErfolg:\nMakelloser Meister (Ebene 16)\nKategorie:\nTorghast" }
